bool MotionController::tripApproachTimeout(const PressureRuntime& rt, float protect_position,
                                           float contact_start_pos, float contact_start_time,
                                           const char* tag)
{
    // 接触超时/最大接近距离保护（防空行程撞底）。与 protect_position 解耦:取
    // "protect_position×0.8" 与绝对上限 kApproachMaxDistCapMm 的较小者,避免配方大限位
    // 把接近距离阈值放大到数倍真实接触间隙、致驱动堵转先于 host 触发(20260629)。
    const float APPROACH_MAX_DIST = fminf(fmaxf(protect_position * 0.8f, 1.0f),
                                          protection::kApproachMaxDistCapMm);
    const float APPROACH_MAX_TIME = protection::kApproachMaxTimeS;
    const float dist = fabsf(rt.pos - contact_start_pos);
    const float t    = rt.now_s - contact_start_time;
    if (dist > APPROACH_MAX_DIST || t > APPROACH_MAX_TIME) {
        system_state = STATE_ERROR;
        // 专用码：与 V2 路径（motion_controller.cpp:2172）一致，GUI 显示
        // "未接触/接近超时"，区别于其它安全保护，便于现场判断空行程撞底。
        error_code   = ERROR_NO_CONTACT;
        SPDLOG_ERROR("{} No-contact abort: dist={:.3f}mm time={:.2f}s", tag, dist, t);
        return true;
    }
    return false;
}

