#ifndef PP_ACHIEVE_H_
#define PP_ACHIEVE_H_
// ──────────────────────────────────────────────────────────────────────
// 位置-压力(PP)模式"达标"判据 —— 纯逻辑，header-only，无任何依赖，便于单测。
//
// 语义（产品定义）：位置或压力**任一**达标即完成（OR，非 AND）。工件尺寸有
// 公差，位置与压力不会在同一位置/同一时刻同时满足，故 AND 会从两个方向失效：
//   • 超尺寸/硬质件：力先到（落点离标称位置多远无所谓）；
//   • 欠尺寸/软质件：位置先到（力建立不到目标）。
// OR 把工件公差自动吸收。
//
// 两条分支：
//   force_at_target = 力进容差带(|F_target-F_actual| <= pressure_tol)
//                     或 已超目标力(F_actual > F_target)
//   pos_at_target   = 到标称位置容差内(|target_pos-pos| <= position_tol)
//                     且 有最小接触力(F_actual >= contact_threshold)
// 位置分支的接触力门用于堵"缺料/超小件在自由行程走到位却没碰到工件 → F≈0 的
// 静默假成功"。力分支在空中 F_abs=|F_target-0| 远超容差，天然不会误触发，无需
// 此门。contact_threshold 须为调用方已解析的有效阈值（0→默认回退由调用方负责，
// 与 detectContactDebounced 同语义）。
// ──────────────────────────────────────────────────────────────────────

namespace pp_achieve {

struct Inputs {
    float f_abs;             // |F_target - F_actual|  [N]
    float f_actual;          // 当前实际力 [N]
    float f_target;          // 目标力 target_pressure [N]
    float pressure_tol;      // 力达标容差 [N]
    float d_abs;             // |target_position - pos|  [mm]
    float position_tol;      // 位置达标容差 [mm]
    float contact_threshold; // 位置分支最小接触力（已解析，>0）[N]
};

struct Result {
    bool force_at_target;
    bool pos_at_target;
    bool achieved() const { return force_at_target || pos_at_target; }
};

inline Result evaluate(const Inputs& in) {
    Result r;
    r.force_at_target = (in.f_abs <= in.pressure_tol) ||
                        (in.f_actual > in.f_target);
    r.pos_at_target   = (in.d_abs <= in.position_tol) &&
                        (in.f_actual >= in.contact_threshold);
    return r;
}

} // namespace pp_achieve

#endif // PP_ACHIEVE_H_

